  "inlineSchema": "// prisma/schema.prisma\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// 1. Bảng Người dùng\nmodel User {\n  id               String  @id @default(uuid())\n  email            String  @unique\n  name             String?\n  password         String?\n  image            String?\n  provider         String?\n  providerId       String?\n  isActive         Boolean @default(true)\n  hasSeenGuide     Boolean @default(false)\n  hasAcceptedTerms Boolean @default(false)\n  role             String  @default(\"user\") // \"user\" hoặc \"super_admin\"\n\n  workspaces WorkspaceMember[]\n  createdAt  DateTime          @default(now())\n}\n\n// 2. Bảng Không gian làm việc\nmodel Workspace {\n  id          String  @id @default(uuid())\n  name        String\n  ownerId     String\n  phoneNumber String?\n\n  plan       String    @default(\"free\")\n  planExpiry DateTime?\n  isAutoPay  Boolean   @default(false)\n  balance    Float     @default(0)\n\n  vtpToken       String?\n  vtpShopId      String?\n  senderAddress  String?\n  senderProvince String?\n  senderDistrict String?\n\n  members        WorkspaceMember[]\n  socialAccounts SocialAccount[]\n  posts          Post[]\n  products       Product[]\n  inboxMessages  InboxMessage[]\n  socialGroups   SocialGroup[]\n  orders         Order[]\n  transactions   Transaction[]\n  createdAt      DateTime          @default(now())\n}\n\n// 3. BẢNG GIAO DỊCH\nmodel Transaction {\n  id          String    @id @default(uuid())\n  workspaceId String\n  amount      Float\n  status      String    @default(\"pending\")\n  description String\n  planName    String?\n  createdAt   DateTime  @default(now())\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n}\n\n// 4. BẢNG VOUCHER\nmodel Voucher {\n  id         String    @id @default(uuid())\n  code       String    @unique\n  discount   Float\n  type       String    @default(\"fixed\")\n  minOrder   Float     @default(0)\n  expiryDate DateTime?\n  usageLimit Int       @default(100)\n  usedCount  Int       @default(0)\n  isActive   Boolean   @default(true)\n  createdAt  DateTime  @default(now())\n}\n\n// 5. Bảng trung gian Thành viên\nmodel WorkspaceMember {\n  id          String    @id @default(uuid())\n  userId      String\n  workspaceId String\n  role        String    @default(\"admin\")\n  user        User      @relation(fields: [userId], references: [id])\n  workspace   Workspace @relation(fields: [workspaceId], references: [id])\n}\n\n// 6. Bảng Tài khoản mạng xã hội\nmodel SocialAccount {\n  id            String  @id @default(uuid())\n  workspaceId   String\n  platform      String\n  platformId    String\n  accountName   String\n  accessToken   String  @db.Text\n  cookies       String? @db.Text\n  isAiAutoReply Boolean @default(false)\n  aiTone        String  @default(\"friendly\")\n\n  workspace Workspace @relation(fields: [workspaceId], references: [id])\n}\n\n// 7. Bảng Bài đăng\nmodel Post {\n  id           String    @id @default(uuid())\n  content      String    @db.Text\n  productUrl   String?\n  status       String    @default(\"draft\")\n  workspaceId  String\n  isSystemPost Boolean   @default(false)\n  workspace    Workspace @relation(fields: [workspaceId], references: [id])\n  userId       String?\n  createdAt    DateTime  @default(now())\n}\n\n// 8. Bảng Sản phẩm\nmodel Product {\n  id          String      @id @default(uuid())\n  workspaceId String\n  name        String\n  description String?\n  price       Float?\n  imageUrl    String?\n  productUrl  String?\n  skuInternal String      @unique\n  totalStock  Int         @default(0)\n  workspace   Workspace   @relation(fields: [workspaceId], references: [id])\n  orderItems  OrderItem[]\n}\n\n// 9. Bảng Hộp thư\nmodel InboxMessage {\n  id          String    @id @default(uuid())\n  workspaceId String\n  platform    String\n  type        String\n  senderName  String\n  senderId    String\n  content     String    @db.Text\n  pageName    String?\n  platformId  String    @unique\n  createdAt   DateTime  @default(now())\n  workspace   Workspace @relation(fields: [workspaceId], references: [id])\n}\n\n// 10. Bảng Quản lý Hội nhóm\nmodel SocialGroup {\n  id          String    @id @default(uuid())\n  workspaceId String\n  platform    String\n  groupId     String    @unique\n  groupName   String\n  pageId      String\n  createdAt   DateTime  @default(now())\n  workspace   Workspace @relation(fields: [workspaceId], references: [id])\n}\n\n// 11. Bảng Đơn hàng\nmodel Order {\n  id              String      @id @default(uuid())\n  workspaceId     String\n  customerName    String\n  customerPhone   String?\n  customerAddress String?\n  province        String?\n  district        String?\n  ward            String?\n  totalAmount     Float\n  status          String      @default(\"confirmed\")\n  shippingCode    String?\n  shippingFee     Float?\n  weight          Int?        @default(500)\n  carrierName     String?\n  items           OrderItem[]\n  createdAt       DateTime    @default(now())\n  workspace       Workspace   @relation(fields: [workspaceId], references: [id])\n}\n\n// 12. Chi tiết đơn hàng\nmodel OrderItem {\n  id        String  @id @default(uuid())\n  orderId   String\n  productId String\n  quantity  Int\n  price     Float\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n}\n\n// 13. Cấu hình Website\nmodel SystemSetting {\n  id           String   @id @default(\"global\")\n  websiteName  String?  @default(\"Dropbuy SaaS\")\n  logoUrl      String?\n  faviconUrl   String?\n  hotline      String?\n  emailSupport String?\n  announcement String?  @db.Text\n  maintenance  Boolean  @default(false)\n  updatedAt    DateTime @updatedAt\n}\n\n// 14. Thông báo hệ thống\nmodel SystemNotification {\n  id        String   @id @default(uuid())\n  targetId  String?\n  title     String\n  content   String   @db.Text\n  type      String   @default(\"info\")\n  isRead    Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n",
